package com.alsafa.native4;
import android.app.Activity;import android.widget.TextView;import com.alsafa.native4.core.*;
/** Rebinds the existing sync button to Native4-only sync. Alpha data remains untouched. */
public final class SyncButtonBinder{private SyncButtonBinder(){}public static void bind(Activity a,CoreDb db,TextView status,Runnable refresh){a.findViewById(R.id.sendOutbox).setOnClickListener(v->{status.setText("جاري تشغيل مزامنة Native4 الجديدة...");Native4SyncRunner.run(a,db,new Native4SyncRunner.Callback(){public void done(Native4SyncCoordinator.Result r){status.setText(Native4SyncRunner.summary(r));if(refresh!=null)refresh.run();}public void failed(Exception e){status.setText("تعذرت مزامنة Native4: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage())+" — البيانات المحلية محفوظة");if(refresh!=null)refresh.run();}});});}}
